func TestFromDenseBugFix(t *testing.T) {
	// Test for the bug where FromDense produced incorrect bitmap when converting from dense representation

	// Create a simple dense bitmap with a few bits set
	dense := make([]uint64, 1024)
	dense[0] = 0x5  // bits 0 and 2 should be set
	dense[1] = 0x9  // bits 64 and 67 should be set

	rb := New()
	rb.FromDense(dense, true)

	// Check that we have the correct bits
	assert.True(t, rb.Contains(0), "Should contain bit 0")
	assert.True(t, rb.Contains(2), "Should contain bit 2")
	assert.True(t, rb.Contains(64), "Should contain bit 64")
	assert.True(t, rb.Contains(67), "Should contain bit 67")

	// Make sure we don't have other bits
	assert.False(t, rb.Contains(1), "Should not contain bit 1")
	assert.False(t, rb.Contains(3), "Should not contain bit 3")
	assert.False(t, rb.Contains(65), "Should not contain bit 65")
	assert.False(t, rb.Contains(66), "Should not contain bit 66")

	// Check total count
	assert.Equal(t, 4, rb.GetCardinality(), "Should have 4 bits set")

	// Verify the iterator gives correct values
	expected := []uint32{0, 2, 64, 67}
	actual := make([]uint32, 0)
	it := rb.Iterator()
	for it.HasNext() {
		actual = append(actual, it.Next())
	}
	assert.Equal(t, expected, actual, "Iterator should return correct values")
}
EOF
