func TestFromDenseMultipleContainers(t *testing.T) {
	// Test FromDense with bits spanning multiple containers

	// Create a dense bitmap that spans two containers
	// Container 0: bits 0-65535 (words 0-1023)
	// Container 1: bits 65536-131071 (words 1024-2047)
	dense := make([]uint64, 2048)

	// Set some bits in container 0
	dense[0] = 0x1   // bit 0
	dense[1023] = 0x1 // bit 65535 (last bit of container 0)

	// Set some bits in container 1
	dense[1024] = 0x1 // bit 65536 (first bit of container 1)
	dense[2047] = 0x1 // bit 131071 (last bit of our bitmap)

	rb := New()
	rb.FromDense(dense, true)

	// Check bits in container 0
	assert.True(t, rb.Contains(0), "Should contain bit 0")
	assert.True(t, rb.Contains(65535), "Should contain bit 65535")

	// Check bits in container 1
	assert.True(t, rb.Contains(65536), "Should contain bit 65536")
	assert.True(t, rb.Contains(131071), "Should contain bit 131071")

	// Check total count
	assert.Equal(t, 4, rb.GetCardinality(), "Should have 4 bits set")

	// Verify container count
	assert.Equal(t, 2, rb.GetContainerCount(), "Should have 2 containers")
}
EOF
